import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"34、【大壮】 乾下震上","description":"周易尚氏学 - 34、【大壮】 乾下震上","frontmatter":{"title":"34、【大壮】 乾下震上","description":"周易尚氏学 - 34、【大壮】 乾下震上"},"headers":[],"relativePath":"zh/classics/shangshi/039.md","filePath":"zh/classics/shangshi/039.md"}'),s={name:"zh/classics/shangshi/039.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_34、【大壮】-乾下震上" tabindex="-1">34、【大壮】 乾下震上 <a class="header-anchor" href="#_34、【大壮】-乾下震上" aria-label="Permalink to “34、【大壮】 乾下震上”">​</a></h1><p>杂卦云。大壮则止。序卦云。物不可以终壮。故授之以晋。晋者进也。是亦训为止。故与进对文。太玄拟为格。格阻也。亦止也。又拟为夷。夷伤也。故马虞训壮为伤。吴先生曰。伤则必止。二义相因。按说卦震为蕃。蕃有闭义。诗四国于蕃。笺云蕃屏也。周礼大司徒蕃乐。杜子春读蕃为藩。谓藩闭乐器而不用。是蕃与藩通。大壮之所以为止者。以震藩屏闭在前也。四不应初。二三遇敌。下阳全为四所格阻。故日曰贞。言利于贞定不动也。即止也。不止则伤。四五两爻是也。郑王谓为强盛。然注莫古于十翼。莫精于太玄。皆不如是言。疑非易本旨。</p><p>彖曰。大壮。大者壮也。刚以动。故壮。大壮利贞。大者正也。正大而大地之情可见矣。</p><p>大谓乾。乾在下为四所格。故曰大者壮也。盖刚宜静。刚而动必多阻格。释壮之故也。利贞者。贞定。乾象传云。各正性命。保合太和。乃利贞。天地之情。本如是也。</p><p>象曰。雷在天上。大壮。君子以非礼弗履。</p><p>震为履。震履乾。即卑履尊。非礼甚矣。陆绩曰。君子见卑履尊。终必消除。故以为戒。大象每相反为义。此其一也。</p><p>初九。壮于趾。征凶。</p><p>有年初应在四。四震为趾。乃四亦阳。初失应。故壮于趾。言趾有所阻格也。又二三亦阳。阳遇阳则窒。故征凶。有二说文有不宜有也。春秋传日月有食之是也。依说文。有孚者。谓不宜于有也。即不孚也。正与象辞孚穷之义合也。</p><h3 id="象曰。壮于趾。其孚穷也。" tabindex="-1">象曰。壮于趾。其孚穷也。 <a class="header-anchor" href="#象曰。壮于趾。其孚穷也。" aria-label="Permalink to “象曰。壮于趾。其孚穷也。”">​</a></h3><p>初得敌。无应。故孚穷。</p><p>九二。贞吉。</p><p>二得中。故贞吉。与下贞历为对文。</p><h3 id="象曰。九二贞吉。以中也。" tabindex="-1">象曰。九二贞吉。以中也。 <a class="header-anchor" href="#象曰。九二贞吉。以中也。" aria-label="Permalink to “象曰。九二贞吉。以中也。”">​</a></h3><p>二承乘皆阳。得敌。似不吉。然而言者。以位中也。</p><p>九三。小人用壮。君子用罔。贞历。羝羊触藩。赢其角。</p><p>三应在上。小人谓上六。君子谓三。乃上六欲应三。而为五所格。故用壮。三欲应上。而为四所格。故用罔。目无也。言三上皆失其用也。故卜问历。中爻互兑。故曰羊。四震为藩。赢缠绕也。三在下卦之上。于交象为角。羝羊触藩。赢其角者。言三欲上升。为九四所阻格。若羝羊以角触藩而不能决。角反为藩所困也。荀爽以五为角。五为角。则藩已决矣。胡有赢象哉。震藩象。易林乾之丰云。藩屏周卫。同人之师云。藩屏汤武。皆以震为藩。而藩与蕃通。说卦震为蕃。即易林所本也。</p><h3 id="象曰。小人用壮。君子罔也。" tabindex="-1">象曰。小人用壮。君子罔也。 <a class="header-anchor" href="#象曰。小人用壮。君子罔也。" aria-label="Permalink to “象曰。小人用壮。君子罔也。”">​</a></h3><p>罔犹否也。</p><p>九四。贞吉。悔亡。藩决不赢。壮于大典之輹。</p><p>四前监重阴利往。故贞吉无悔。故藩决不赢。震为舆。为輹。象曰尚往。是四往五也。四往五。震象毁。而兑为毁折。故曰壮于大舆之輹。盖卦以止为义。藩决则进。进则有伤。五爻丧羊相因而至矣。虞翻因不知輹象。氦輹为腹。非。</p><h3 id="象曰。藩决不赢。尚往也。尚往言上进居五。" tabindex="-1">象曰。藩决不赢。尚往也。尚往言上进居五。 <a class="header-anchor" href="#象曰。藩决不赢。尚往也。尚往言上进居五。" aria-label="Permalink to “象曰。藩决不赢。尚往也。尚往言上进居五。”">​</a></h3><p>六五。丧羊于易。无悔。</p><p>兑为羊。兑毁折故丧羊。易。释文云。陆作场。谓疆场也。古文往往如是。说文场田畔也。诗小雅。疆场有瓜。丧羊于场。言丧羊于田畔也。诸家作难易解。不辞甚矣。惟场象无有详者。按震为阪。说文阪坡也。山协也。诗小雅。瞻彼阪田。场既为田畔。疑仍震象也。然虽丧羊。下有应得中。亦无悔也。</p><h3 id="象曰。丧羊于易。位不当也。" tabindex="-1">象曰。丧羊于易。位不当也。 <a class="header-anchor" href="#象曰。丧羊于易。位不当也。" aria-label="Permalink to “象曰。丧羊于易。位不当也。”">​</a></h3><p>位不当。释丧羊之故也。</p><p>上六。羝羊触藩。不能退。不能遂。无攸利。艰则吉。</p><p>卦全体兑象。故仍曰抵羊。上欲应三。而为五所格。五亦阴得故。三之藩在四。上之藩在五。故退欲来三。为藩所阻。进欲前往。而道已穷。故不能退不能遂。巽为利。巽伏故无攸利。然上当位有应。艰贞自守。终吉也。</p><h3 id="象曰。不能退。不能遂。不详也。艰则吉。咎不长也。" tabindex="-1">象曰。不能退。不能遂。不详也。艰则吉。咎不长也。 <a class="header-anchor" href="#象曰。不能退。不能遂。不详也。艰则吉。咎不长也。" aria-label="Permalink to “象曰。不能退。不能遂。不详也。艰则吉。咎不长也。”">​</a></h3><p>释文云。详审也。审慎也。言不能退不能遂之故。咎在不慎审于始而妄动也。郑虞王肃王弼皆释详为善。于义亦通。三上为正应。终必和合。故曰咎不长。</p>',29)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
